import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class TaskDueSorterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object guard(java.util.concurrent.Callable<Object> body) {
        try {
            return body.call();
        } catch (Exception e) {
            return "<threw " + e.getClass().getSimpleName() + ">";
        }
    }

    public static void main(String[] args) {
        List<Chore> chores = new ArrayList<>(Arrays.asList(
                new Chore("mop", null),
                new Chore("taxes", "2024-04-15"),
                new Chore("dust", null),
                new Chore("vet", "2024-01-09"),
                new Chore("bank", "2024-04-15")));

        check("sortedNames", "[vet, bank, taxes, dust, mop]",
                String.valueOf(guard(() -> TaskDueSorter.sortedNames(chores))));
        check("caller's list untouched", "mop", chores.get(0).name());
        check("countUndated", 2, TaskDueSorter.countUndated(chores));

        List<Chore> allNull = Arrays.asList(new Chore("zebra", null), new Chore("ant", null));
        check("all undated fall back to name order", "[ant, zebra]",
                String.valueOf(guard(() -> TaskDueSorter.sortedNames(allNull))));
        check("countUndated(all null)", 2, TaskDueSorter.countUndated(allNull));

        List<Chore> noNulls = Arrays.asList(new Chore("b", "2023-12-31"), new Chore("a", "2023-01-01"));
        check("no nulls still sorts by date", "[a, b]",
                String.valueOf(guard(() -> TaskDueSorter.sortedNames(noNulls))));
        check("countUndated(no nulls)", 0, TaskDueSorter.countUndated(noNulls));

        check("sortedNames(empty)", "[]",
                String.valueOf(guard(() -> TaskDueSorter.sortedNames(new ArrayList<Chore>()))));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

