import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/** A to-do item; due may be null when no date has been set. Provided -- do not edit. */
record Chore(String name, String due) { }

/**
 * TASK: Sort chores by due date with UNDATED ones pushed to the end.
 *
 * The due field is an ISO date like "2024-03-09" or null. Dates in that format
 * sort correctly as plain strings, so natural String order is all you need --
 * except that natural order explodes on null.
 *
 * Build the comparator as
 *     Comparator.comparing(Chore::due, Comparator.nullsLast(Comparator.naturalOrder()))
 *               .thenComparing(Chore::name)
 * so that:
 *   - dated chores come first, earliest date first,
 *   - undated chores come last,
 *   - chores that tie (including two undated ones) fall back to name order.
 *
 * sortedNames(chores) returns the names in that order, sorting a COPY so the
 * caller's list is unchanged. An empty list gives an empty list.
 *
 * Note the two-argument Comparator.comparing: the second argument says how to
 * compare the extracted keys, which is where nullsLast belongs.
 */
public class TaskDueSorter {

    public static List<String> sortedNames(List<Chore> chores) {
        Comparator<Chore> byDueThenName =
                Comparator.comparing(Chore::due, Comparator.nullsLast(Comparator.<String>naturalOrder()))
                        .thenComparing(Chore::name);
        List<Chore> copy = new ArrayList<>(chores);
        copy.sort(byDueThenName);
        List<String> names = new ArrayList<>();
        for (Chore chore : copy) {
            names.add(chore.name());
        }
        return names;
    }

    public static int countUndated(List<Chore> chores) {
        int count = 0;
        for (Chore chore : chores) {
            if (chore.due() == null) {
                count++;
            }
        }
        return count;
    }
}
